static struct bch_member members_v2_get(struct bch_sb_field_members_v2 *mi, int i)
{
	struct bch_member ret, *p = __bch2_members_v2_get_mut(mi, i);
	size_t copy_len = min_t(size_t, le16_to_cpu(mi->member_bytes), sizeof(ret));

	memset(&ret, 0, sizeof(ret));

	if ((void *) p + copy_len > (void *) mi + vstruct_bytes(&mi->field))
		return ret;

	memcpy(&ret, p, copy_len);
	return ret;
}

